INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('8d174849-e43c-4ad6-8083-c0ad9688ea09', '21feff02-016d-46e2-bb9d-c27495133b1b', '81. óra: Százalékszámítás', '1 egész = 100%, 1% fogalma (századrész), százalék és törtrész kapcsolata.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "4f6717a9-57e3-49ac-a2d2-25b321490598", "text": "Mit jelent a 1% (egy százalék) fogalma?", "type": "multiple-choice", "options": [{"id": "fce317e7-2e99-4ad5-be87-71f55e38f9bd", "text": "Az egész mennyiség 1/100-ad részét (századrészét)", "isCorrect": true}, {"id": "29e96039-6e8f-49ec-942d-a08d6008bcd5", "text": "Az egész 1/10-ed részét", "isCorrect": false}, {"id": "ba7df948-ed3f-45a5-bae8-6ad29bb644c7", "text": "100 egészet", "isCorrect": false}, {"id": "69bc5655-97e6-4eea-af49-7393cc20bd2f", "text": "Az egész felét", "isCorrect": false}], "timeLimit": 15}, {"id": "a582b438-81c4-4ec8-9029-c9bfef298080", "text": "Hány százalék felel meg a teljes egésznek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "1b49dcfc-22f1-43c6-aa33-e23d0bf74d1a", "text": "Hány százalék felel meg a fél (1/2) mennyiségnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "50"}, {"id": "ca455009-9a22-4a3f-b767-4d8c226cce42", "text": "Hány százalék felel meg a negyed (1/4) mennyiségnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "25"}, {"id": "8e9ee2a5-fbb2-4bcd-bf46-3593aa4506d4", "text": "Hány százalék felel meg a háromnegyed (3/4) mennyiségnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "75"}, {"id": "70f406d4-9bd5-4760-add2-83880e435459", "text": "A 10% az egész 1/10-ed részét jelenti.", "type": "true-false", "options": [{"id": "e93543e2-71ad-4552-b6ba-84e8ba74d2b6", "text": "Igaz", "isCorrect": true}, {"id": "1c59656d-1b25-4c1d-bcf8-150898653821", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "8a9dcc98-a0f1-4173-b0d9-172aadc991ab", "text": "A 20% az egész 1/5-öd részének felel meg.", "type": "true-false", "options": [{"id": "9634e0f5-aa85-491d-97e1-0981980ed313", "text": "Igaz", "isCorrect": true}, {"id": "9ada226f-4ffb-42cf-8a45-50376ef261b6", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('3cb302a6-c215-468c-8e64-f823f894e739', '21feff02-016d-46e2-bb9d-c27495133b1b', '82. óra: A százalékszámítás gyakorlása', 'Százalékérték kiszámítása következtetéssel (1% kiszámítása) vagy törtrésszel.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "ead6024e-9b97-4c9f-a8fb-03342da9711a", "text": "Mennyi 500 Ft-nak a 10%-a? (500 / 10)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "50"}, {"id": "2f74592a-9e86-4dd8-b336-928cbcf0bd56", "text": "Mennyi 500 Ft-nak az 1%-a? (500 / 100)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "e66172dc-69d1-4b93-8d99-69df0d46a75e", "text": "Mennyi 500 Ft-nak a 20%-a? (500 * 0,2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "09822300-6761-4367-80f3-d4acd68855de", "text": "Mennyi 800 kg-nak az 50%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "400"}, {"id": "bc140f38-92ba-4e00-8122-a06a3021c646", "text": "A százalékérték kiszámításához az alapmennyiséget megszorozzuk a százaléklábbal és elosztjuk 100-zal.", "type": "true-false", "options": [{"id": "8b43ec2f-bedb-426d-9640-74fcb8b92c75", "text": "Igaz", "isCorrect": true}, {"id": "0daa9705-bb2a-479f-ad4f-332616cbf0fe", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "083678f5-9ce5-4513-9d0d-217d0b505a5d", "text": "Mennyi 200 Ft-nak a 25%-a? (200 / 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "50"}, {"id": "c9d013d3-91fb-4156-8f5d-459129c62893", "text": "Mennyi 1000 Ft-nak a 30%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "300"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('aa6aed1f-ef09-48dd-a0dc-75f9e069edab', '21feff02-016d-46e2-bb9d-c27495133b1b', '83. óra: Feladatmegoldás', 'Százalékszámítással kapcsolatos hétköznapi szöveges feladatok.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "d0a22809-85bf-447a-9827-4cdf55092220", "text": "Egy 10 000 Ft-os cipő árából 20% kedvezményt adnak. Mennyi a kedvezmény összege? (10000 * 0,2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2000"}, {"id": "dfd0ecd9-e4c6-4bd7-a578-b1c7399dbdb3", "text": "Egy 10 000 Ft-os cipő árából 20% kedvezményt adnak. Mennyi a kedvezményes ár? (10000 - 2000)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8000"}, {"id": "0c8e2ee0-dbd6-4a9f-8d6b-562ffd9bf1dc", "text": "Egy iskolában 400 tanuló van. 55%-uk lány. Hány lány jár az iskolába? (400 * 0,55)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "220"}, {"id": "0efe2656-a712-4fdc-a9bd-d385016837e2", "text": "Hány fiú jár az iskolába? (400 - 220)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "180"}, {"id": "603973f6-cf06-4a9f-a475-06c7929db411", "text": "A kedvezményes ár kiszámításához az eredeti árból kivonjuk a kedvezmény értékét.", "type": "true-false", "options": [{"id": "e0de94af-de7f-4f6a-94b1-2687824cb450", "text": "Igaz", "isCorrect": true}, {"id": "9a94b185-ceb6-4733-88c5-efe91db4612d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "20ef8c42-72f5-4502-943d-b1b5c812f3b9", "text": "Ha egy ár 10%-kal nő, az új ár az eredeti ár 110%-a lesz.", "type": "true-false", "options": [{"id": "ee0cebbf-9a97-41c9-8302-fed0262b384b", "text": "Igaz", "isCorrect": true}, {"id": "33212abf-c672-4800-873b-a06576bbf269", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "a1e498e1-841f-4c47-8f3d-77350008c61c", "text": "Mennyi 50 000 Ft 5%-os kamata 1 évre?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2500"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('a6241ded-0e9f-4349-8039-124a52f768fb', '21feff02-016d-46e2-bb9d-c27495133b1b', '84. óra: Feladatmegoldás II.', 'Összetettebb százalékszámítási feladatok, árleértékelések, drágulások.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "fe335d23-9c9e-4f91-b618-83b0a146a91f", "text": "Egy 20 000 Ft-os kabát árát 15%-kal felemelték. Hány Ft a drágulás értéke? (20000 * 0,15)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3000"}, {"id": "a03c0d64-1bb4-45d8-9d1c-98ae6833ea65", "text": "Mennyi a kabát új ára a 15%-os drágulás után? (20000 + 3000)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "23000"}, {"id": "be9b5d6b-8d67-4c86-9d2a-94a61c4567e9", "text": "A 30-as létszámú osztályban a tanulók 10%-a hiányzott. Hány tanuló hiányzott?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3"}, {"id": "d4b661d7-e949-4455-8502-c5cb8b0050a0", "text": "Hány tanuló volt jelen az osztályban? (30 - 3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "27"}, {"id": "86b0e351-49e2-4510-8f5f-de64b438442e", "text": "Ha a 100 Ft-os termék ára 50%-kal csökken, majd a kedvezményes ár 50%-kal nő, az ár visszatér 100 Ft-ra.", "type": "true-false", "options": [{"id": "e2db51c8-56dd-492b-81ff-b02fdfa04e7d", "text": "Igaz", "isCorrect": false}, {"id": "d3ad0b3d-f363-42f0-a4c9-79520352aa7c", "text": "Hamis (50 Ft 50%-os növekedése 75 Ft lesz!)", "isCorrect": true}], "timeLimit": 15}, {"id": "2a1a777b-6071-4090-928f-4b7cc2e4c986", "text": "Mennyi 400 liter 75%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "300"}, {"id": "2137434d-e01b-4a97-b0f9-e7711c7edd37", "text": "A százalékszámítás alapvető ismeret a mindennapi pénzügyi tájékozódáshoz.", "type": "true-false", "options": [{"id": "7fa4c064-b792-4b2f-ad83-f3c3532094d4", "text": "Igaz", "isCorrect": true}, {"id": "356828d8-b207-4e35-8abe-4741ab20e23a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('51309f6d-1513-49cb-8145-6f2f86ffff33', '21feff02-016d-46e2-bb9d-c27495133b1b', '85. óra: Projektóra', 'Családi költségvetés készítése megadott keretből, százalékos megoszlások számítása.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "571eaf8e-e290-428b-ae39-c6df260da4f6", "text": "Ha a család havi jövedelme 400 000 Ft, és 30%-ot költenek lakhatásra, hány Ft a lakhatási költség?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "120000"}, {"id": "2659b252-7821-48a1-93f7-a4f8bc90e8ed", "text": "Ha a jövedelem 40%-át élelmiszerre költik, hány Ft megy élelmiszerre? (400000 * 0,4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "160000"}, {"id": "03b32a38-d667-4485-9cf7-95aa039d0676", "text": "Hány Ft marad megtakarításra és egyéb kiadásokra? (400000 - 120000 - 160000)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "120000"}, {"id": "1b26e1c4-1003-4506-bf1a-7ac6de323811", "text": "A családi költségvetés készítésekor a kiadások összege nem haladhatja meg a bevételeket.", "type": "true-false", "options": [{"id": "cc23b8ed-b844-458d-9a5b-20d53b8cde8b", "text": "Igaz", "isCorrect": true}, {"id": "3d8c6813-03ae-413a-a595-e0751a835ab3", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "6d5dfff5-cc20-4255-841c-19735cebb7ee", "text": "Hány százalékot tesz ki a megmaradt 120 000 Ft a 400 000 Ft-os jövedelemből?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "6993d713-bb6a-4c9a-af32-c313c1ff6a84", "text": "A százalékos megoszlás kördiagramon ábrázolva jól szemlélteti a kiadások arányát.", "type": "true-false", "options": [{"id": "16661369-9010-4c9b-ba6c-3cc86363aa88", "text": "Igaz", "isCorrect": true}, {"id": "7d6d23e7-0377-48bf-811e-08c8aff94b62", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "7d278d31-c399-45f0-9535-7d8aad0932aa", "text": "A tudatos pénzügyi tervezés segít elkerülni az eladósodást.", "type": "true-false", "options": [{"id": "7912ae47-dc2d-4e79-bfa2-bdc48a5200d7", "text": "Igaz", "isCorrect": true}, {"id": "c547d13d-7c60-4d8f-9b72-8086fc434a6f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('d24fcb81-51c5-42e2-a2d0-0c3bf9150c35', '21feff02-016d-46e2-bb9d-c27495133b1b', '86. óra: Nyitott mondatok', 'Lebontogatás (visszafelé gondolkodás) és próbálgatás módszere egyenleteknél.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "248eea9e-14e3-4cec-b429-648e077536a0", "text": "Mit jelent a lebontogatás (visszafelé gondolkodás) módszere?", "type": "multiple-choice", "options": [{"id": "8f4aed3c-37fa-4bea-9004-5b0219b9bc68", "text": "A végeredményből kiindulva az inverz (ellentétes) műveleteket végezzük el visszafelé", "isCorrect": true}, {"id": "13ef2557-a212-4487-92f5-a36f2ca9c5ab", "text": "Visszafelé írjuk le a számokat", "isCorrect": false}, {"id": "4e58ea39-0ecc-401a-9b2f-17a943d83111", "text": "Tippelünk egy számot és feladjuk", "isCorrect": false}, {"id": "2542a496-8e80-488f-9b55-3a2e9f0b0030", "text": "Kivonunk mindent 100-ból", "isCorrect": false}], "timeLimit": 15}, {"id": "c2d8a74d-229d-4754-8da5-55c52c54fa0e", "text": "Melyik szám teszi igazzá: 2 * x + 5 = 17? (17 - 5 = 12, 12 / 2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "703aee7c-4ae0-473d-bb3d-edc54bb5fb64", "text": "Melyik szám teszi igazzá: (y - 4) : 3 = 5? (5 * 3 = 15, 15 + 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "19"}, {"id": "07d32c07-1fc9-4f93-8344-acf04dda3a99", "text": "Az ellenőrzés során a kapott értéket behelyettesítjük az eredeti nyitott mondatba.", "type": "true-false", "options": [{"id": "64152efd-0ae1-4f30-81e2-6962187221f2", "text": "Igaz", "isCorrect": true}, {"id": "05a5af0e-6e34-4e76-b2a1-e9300bac0871", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "31fe375a-fd08-49e0-94c6-9c83f0d395af", "text": "Melyik szám teszi igazzá: 3 * a - 10 = 20?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "682ccf76-a35b-4993-9b5a-d634a8e78966", "text": "A próbálgatásos módszernél rendszerezett táblázatot érdemes vezetni.", "type": "true-false", "options": [{"id": "ec2b9457-226c-45e1-bcef-4ec55fc736a7", "text": "Igaz", "isCorrect": true}, {"id": "2b58e40c-19b6-419e-aa22-b9d0450c156a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "0d7b29da-48df-4d39-9101-53f7f674a53b", "text": "Melyik szám teszi igazzá: x / 4 + 2 = 7?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('0f1260dd-cebe-4ea3-bf10-ef5928b3018d', '21feff02-016d-46e2-bb9d-c27495133b1b', '87. óra: Feladatmegoldás: Nyitott mondatok', 'Gyakorlás: lebontogatási módszer alkalmazása egyenletek és egyenlőtlenségek megoldásában.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "8dcd9da1-9496-41c1-a11f-71b24b6cbcb6", "text": "Melyik szám teszi igazzá: 4 * (x + 2) = 36? (36/4 = 9, 9-2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "7"}, {"id": "e45b6c32-b170-4a85-9706-50bfa0e9f4ff", "text": "Melyik szám teszi igazzá: 5 * y - 12 = 38? (50/5)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "1f9b0862-6795-48cf-8e03-90a224e2fc70", "text": "Ha az alaphalmaz a természetes számok (0, 1, 2, ...), hány megoldása van a 2 * x < 6 egyenlőtlenségnek? (x = 0, 1, 2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3"}, {"id": "92cbd871-69f8-4f3a-88a7-3e5ef3ac6ec3", "text": "Az egyenlőtlenségeknek több megoldása is lehet egy megadott alaphalmazon.", "type": "true-false", "options": [{"id": "232ce8a3-1e57-409c-ba77-7b7281ef9db3", "text": "Igaz", "isCorrect": true}, {"id": "2b0bf692-4102-4463-b263-5bc7f870e3e6", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "aefd097f-9685-44f3-b4ec-1bfd4af19a9f", "text": "Melyik szám teszi igazzá: (z + 10) / 2 = 15?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "ff26cadd-cb62-4725-a1f5-79db71829b28", "text": "Ha az egyenletnek nincs megoldása az adott alaphalmazon, az igazsághalmaz az üres halmaz.", "type": "true-false", "options": [{"id": "61f015fb-edf8-4bea-8043-d7ad35047680", "text": "Igaz", "isCorrect": true}, {"id": "787d993a-a9ae-4667-b216-4e32255a0205", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "41e01b1b-a74a-48c8-9488-5d1093674ed0", "text": "Melyik szám teszi igazzá: 10 * x - 25 = 75?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('6442a017-a4e3-47d1-8e6c-5b187ac0e1f2', '21feff02-016d-46e2-bb9d-c27495133b1b', '88. óra: Gyakorlóóra', 'Nyitott mondatok és műveleti sorrend gyakorlása.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "97cf17cf-e6e6-4005-a014-976a5480e5e9", "text": "Melyik szám teszi igazzá: 3 * x + 7 = 34?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "9"}, {"id": "103f56a6-a0c5-456e-960d-0d02dbeda556", "text": "Melyik szám teszi igazzá: (x - 5) * 6 = 42?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "cfeed7aa-da12-4cea-8d96-e279b3bad151", "text": "A lebontogatás lépései során az utolsóként elvégzett művelet inverzével kezdjük a számolást.", "type": "true-false", "options": [{"id": "3f15d513-11e9-4f9e-92f6-63b2a8536946", "text": "Igaz", "isCorrect": true}, {"id": "9f777d6d-4f77-4854-bd54-9596724ea2d4", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "60fd7127-257a-4ece-8d43-3928361862f2", "text": "Mennyi x értéke, ha 50 - 2 * x = 30? (2x = 20)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "0553a03c-f9de-4bca-9d06-aa7784bd626a", "text": "Mennyi y értéke, ha y / 3 - 4 = 6?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "6098def5-2557-4a93-a663-a6e8fb9b0a61", "text": "Az ellenőrzés kihagyása növeli a hibázás kockázatát.", "type": "true-false", "options": [{"id": "0177a0e3-9089-4159-8c67-18ddf965e45f", "text": "Igaz", "isCorrect": true}, {"id": "94b08268-da51-4209-b3e6-7ab17f0ab530", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "24657230-e853-4eae-8fd9-c1b1325a822b", "text": "Melyik szám teszi igazzá: 8 * a + 4 = 68?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('cdb6fb2c-9c94-459b-b7a5-38f3535fc6de', '21feff02-016d-46e2-bb9d-c27495133b1b', '89. óra: Szöveges feladatok', 'Szöveges feladatok megoldása nyitott mondatok felírásával, ábrakészítéssel.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "7bf015a5-57d4-45df-acd8-8a8f5285b967", "text": "Gondoltam egy számot, megszóroztam 3-mal, hozzáadtam 12-őt és 45-öt kaptam. Mi volt a szám? (3x + 12 = 45 -> 3x = 33)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "11"}, {"id": "994f9158-4f28-44dc-8b97-cd6a286734f5", "text": "Gondoltam egy számot, kivontam belőle 8-at, megszoroztam 4-gyel és 40-et kaptam. Mi volt a szám? ((x-8)*4 = 40 -> x-8 = 10)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "18"}, {"id": "dd25f57d-e94c-468c-9f2c-7be3f07b6f7f", "text": "Katinak 3-szor annyi matricája van, mint Petinek. Összesen 48 matricájuk van. Hány matricája van Petinek? (x + 3x = 48 -> 4x = 48)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "f8251258-1521-49ba-a75c-854b4ed92248", "text": "Hány matricája van Katinak? (3 * 12)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "36"}, {"id": "d89c798f-5407-423f-968e-ce936d4f4070", "text": "A szöveges feladatok megoldásának lépései: Értelmezés -> Adatok/Ismeretlen -> Nyitott mondat -> Számolás -> Ellenőrzés -> Válaszmondat.", "type": "true-false", "options": [{"id": "a97c38a1-0473-4c56-a884-bfeb7f0c296e", "text": "Igaz", "isCorrect": true}, {"id": "c8e3483f-9e7d-4434-a0e3-ac3103454a36", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "1f25c620-bf0c-4547-b2d3-e841914689ce", "text": "Ha a feladatban a ''kétszer annyi'' kifejezés szerepel, 2-vel való szorzásra gondolunk.", "type": "true-false", "options": [{"id": "bcef826e-5c16-4656-a3e7-1d3d1ffb0810", "text": "Igaz", "isCorrect": true}, {"id": "503e64d4-9e91-4c21-bde2-f7f6fa4e68fc", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "01e11134-5978-4360-8449-3ec7f4a684f2", "text": "Gondoltam egy számot, elosztottam 5-tel, hozzáadtam 7-et és 12-őt kaptam. Mi a szám?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "25"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('d88bcfe2-effc-4060-b168-fc831aeb70df', '21feff02-016d-46e2-bb9d-c27495133b1b', '90. óra: Gyakorlóóra', 'Matematikai szövegezésű feladatok gyakorlása, ábrakészítés, összefüggések.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "538be96f-725a-4d26-91c9-b5dbe5fb6c7b", "text": "Apa 4 évvel idősebb, mint Anya. Életkoruk összege 76 év. Hány éves Anya? (2x + 4 = 76 -> 2x = 72)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "36"}, {"id": "fec1987f-cea0-42cc-8e97-ed2adb4b2f25", "text": "Hány éves Apa? (36 + 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}, {"id": "e78b81a5-241e-4e09-9575-352f376d2d92", "text": "Egy téglalap kerülete 40 cm. Hosszabbik oldala 4 cm-rel hosszabb a rövidebbnél. Hány cm a rövidebb oldal? (2*(x + x+4) = 40 -> 4x + 8 = 40)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "d58b81e9-ea43-4ba4-91ed-2d0d8432fb81", "text": "Hány cm a hosszabbik oldal? (8 + 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "081b3478-fca3-40ae-872c-6e7892389e64", "text": "A szakaszos ábrázolás nagymértékben segít a szöveges feladatok összefüggéseinek megértésében.", "type": "true-false", "options": [{"id": "a800ea45-c67d-4df2-9276-cf92a74f626d", "text": "Igaz", "isCorrect": true}, {"id": "e80cbbae-4637-4741-99cd-5e852bb28b80", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "71c77ba3-1c39-4fd7-bf55-53e9763e6310", "text": "Három egymást követő egész szám összege 45. Mi a legkisebb szám? (x + x+1 + x+2 = 45 -> 3x + 3 = 45)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "14"}, {"id": "f91e56a6-927c-41fc-bb5a-589bc23fb05b", "text": "A válaszmondat felírása kötelező a szöveges feladat végén.", "type": "true-false", "options": [{"id": "5600697e-7c9f-4840-8bf6-ad85eadc510f", "text": "Igaz", "isCorrect": true}, {"id": "652dcf7b-3902-4bee-82ed-d24bbe74753c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;